<script setup lang="ts">
import type { Comparison } from '../types/compare'
defineProps<{ result: Comparison }>()
const labels: Record<string,string> = {STAFF:'共同制作人员与机构',VOICE:'共同声优（自然人）',CHARACTER:'共同出场角色'}
function source(id: string) { return `https://bgm.tv/${id.startsWith('person:')?'person':'character'}/${id.split(':').at(-1)}` }
</script>
<template>
  <div class="comparison-sides"><section v-for="(side,i) in [result.a,result.b]" :key="i" class="panel"><h2>{{ i===0?'作品 A':'作品 B' }} · {{ side.entity.nameCn || side.entity.name || side.subjectId }}</h2><p v-if="side.error" class="feedback error">{{ side.error }}</p><p>{{ side.entity.year || '发行年未知' }} · {{ side.entity.format || '形式未知' }} · 社区评分 {{ side.entity.score || '暂无' }}</p><p class="muted">配音名册 {{ side.metadata.cast.loadedRows }}/{{ side.metadata.cast.total || '未知' }} 行{{ side.metadata.cast.complete?'（已读完）':'（部分）' }}；制作名册 {{ side.metadata.staff.loadedRows }}/{{ side.metadata.staff.total || '未知' }} 行{{ side.metadata.staff.complete?'（已读完）':'（部分）' }}</p><RouterLink :to="`/explore/anime/${side.subjectId}`">查看作品详情</RouterLink></section></div>
  <section class="panel"><h2>标签共同点</h2><p v-if="result.tagSimilarity !== null">现有标签相似度 {{ result.tagSimilarity }}%</p><p v-else class="muted">标签资料不足，暂不能计算相似度。</p><p>{{ result.sharedTags.join('、') || '当前没有已知共有标签' }}</p><p class="muted">{{ result.methodology }}</p></section>
  <section v-for="group in result.groups" :key="group.kind" class="panel"><h2>{{ labels[group.kind] }} · {{ group.items.length }}{{ group.complete && !group.truncated?'':'+' }}</h2><p class="muted">{{ group.notice }}{{ group.truncated?'；当前最多展示500项':'' }}</p><p v-if="!group.items.length">{{ group.complete?'在来源当前名单中未发现共同项。':'尚不能完整比较，先补充两侧资料。' }}</p><div v-if="group.kind === 'STAFF' && group.items.length" class="table-scroll"><table><caption>共同制作人员与双方职务</caption><thead><tr><th scope="col">人员 / 机构</th><th scope="col">作品 A 职务</th><th scope="col">作品 B 职务</th></tr></thead><tbody><tr v-for="item in group.items" :key="item.entity.id"><td><a :href="item.entity.sourceUrl" target="_blank" rel="noopener noreferrer">{{ item.entity.label }}</a></td><td>{{ item.rolesA.map(role => role.label).join('、') || '职务未知' }}</td><td>{{ item.rolesB.map(role => role.label).join('、') || '职务未知' }}</td></tr></tbody></table></div><template v-else><details v-for="item in group.items" :key="item.entity.id" class="common-row"><summary>{{ item.entity.label }} <small>{{ item.entity.providerType === 1?'人员':item.entity.category === 'CHARACTER'?'虚构角色':'机构/类型待核对' }}</small></summary><p v-if="group.kind==='STAFF'">A：{{ item.rolesA.map(r=>r.label).join('、') || '职务未知' }}<br>B：{{ item.rolesB.map(r=>r.label).join('、') || '职务未知' }}</p><template v-else-if="group.kind==='VOICE'"><p v-for="(credits,i) in [item.castA,item.castB]" :key="i">{{ i===0?'A':'B' }}：<span v-for="credit in credits" :key="credit.id"><a :href="source(credit.characterUid)" target="_blank" rel="noopener noreferrer">角色 {{ credit.characterUid.split(':').at(-1) }}</a>（{{ credit.language || '语种未知' }}） </span></p></template><a :href="item.entity.sourceUrl" target="_blank" rel="noopener noreferrer">核对实体来源</a></details></template></section>
</template>
<style scoped>.comparison-sides{display:grid;grid-template-columns:1fr 1fr;gap:20px}.comparison-sides .panel{min-width:0}.common-row{padding:12px 0;border-bottom:1px solid #e4ebde;font-size:13px}.common-row summary{cursor:pointer;min-height:32px}.common-row small{color:#7e9383;margin-left:8px}.common-row p{line-height:1.9}@media(max-width:650px){.comparison-sides{grid-template-columns:1fr;gap:0}}</style>
